SELECT CURRENT_TIMESTAMP() checked_at_utc,'registry' source,TO_JSON_STRING(STRUCT(mapping_id,flow,product_scope,is_credit_shell,payment_source_type,payment_method_source,payment_channel_source,sap_payment_method,sap_payment_channel,approval_state,effective_start,effective_end,approved_at,retired_at,evidence_type,evidence_reference)) payload FROM `pacific-plating-282708.sap_integration_v3.payment_mapping_registry` WHERE payment_method_source='EDC' OR sap_payment_channel LIKE '%EDC%' UNION ALL SELECT CURRENT_TIMESTAMP(),'sap_mirror',TO_JSON_STRING(STRUCT(PaymentMethod,PaymentChannel,TransactionStatus,COUNT(*) AS document_rows,COUNT(DISTINCT U_OrderItem) AS distinct_items)) FROM `pacific-plating-282708.sap_integration_v2.SAP_LIVE_FULL` WHERE PaymentChannel LIKE '%EDC%' OR PaymentChannel LIKE '%Transfer%' GROUP BY PaymentMethod,PaymentChannel,TransactionStatus;